CREATE TABLE IF NOT EXISTS tenants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,state VARCHAR(80),lga VARCHAR(120),country VARCHAR(80) DEFAULT 'Nigeria',school_type VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(60) NOT NULL,name VARCHAR(180) NOT NULL,active TINYINT DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS classes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120),section VARCHAR(80),session_name VARCHAR(80),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS subjects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150),code VARCHAR(30),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_no VARCHAR(50),name VARCHAR(180),gender VARCHAR(30),class_id BIGINT UNSIGNED NULL,email VARCHAR(190),phone VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS parents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180),email VARCHAR(190),phone VARCHAR(40),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS teachers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180),email VARCHAR(190),phone VARCHAR(40),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS staff(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180),department VARCHAR(120),role_title VARCHAR(120),salary DECIMAL(14,2) DEFAULT 0,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,attendance_date DATE NOT NULL,status VARCHAR(20),reason VARCHAR(255),client_id VARCHAR(100),UNIQUE KEY ua(tenant_id,student_id,attendance_date));
CREATE TABLE IF NOT EXISTS results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,score DECIMAL(6,2),max_score DECIMAL(6,2) DEFAULT 100,grade VARCHAR(5),remark VARCHAR(120),status VARCHAR(20) DEFAULT 'draft',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS fees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180),amount DECIMAL(14,2),due_date DATE,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS invoices(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,reference VARCHAR(100) UNIQUE,amount DECIMAL(14,2),paid DECIMAL(14,2) DEFAULT 0,status VARCHAR(30),due_date DATE,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,invoice_id BIGINT UNSIGNED,reference VARCHAR(100) UNIQUE,amount DECIMAL(14,2),status VARCHAR(30),channel VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS courses(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180),description TEXT,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS lessons(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,course_id BIGINT UNSIGNED,title VARCHAR(180),content MEDIUMTEXT,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS books(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220),author VARCHAR(180),isbn VARCHAR(80),copies INT DEFAULT 1,available INT DEFAULT 1,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220),description TEXT,due_date DATE,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS exams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220),duration_minutes INT DEFAULT 60,status VARCHAR(30),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS announcements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,title VARCHAR(220),body TEXT,channel VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS inventory(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180),category VARCHAR(120),quantity INT DEFAULT 0,reorder_level INT DEFAULT 0,unit_cost DECIMAL(14,2),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS assets(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180),serial_no VARCHAR(120),location VARCHAR(120),condition_status VARCHAR(50),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS vehicles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120),plate_no VARCHAR(40),capacity INT,status VARCHAR(40),INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS hostels(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150),rooms INT,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS health_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED,record_type VARCHAR(100),severity VARCHAR(40),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS discipline(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED,category VARCHAR(100),severity VARCHAR(40),action_taken VARCHAR(255),notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS marketplace_products(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NULL,vendor_name VARCHAR(180),name VARCHAR(220),category VARCHAR(120),price DECIMAL(14,2),active TINYINT DEFAULT 1);
CREATE TABLE IF NOT EXISTS marketplace_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,product_id BIGINT UNSIGNED,quantity INT,total DECIMAL(14,2),status VARCHAR(40),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS plans(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100),price_monthly DECIMAL(14,2),student_limit INT,teacher_limit INT,storage_limit_mb INT,whatsapp_limit INT,ai_credits INT);
CREATE TABLE IF NOT EXISTS subscriptions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED,plan_id BIGINT UNSIGNED,status VARCHAR(30),starts_at DATE,ends_at DATE,INDEX(tenant_id));
CREATE TABLE IF NOT EXISTS audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NULL,action VARCHAR(180),entity_type VARCHAR(100),details TEXT,ip_address VARCHAR(64),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id));
